package Utils;




public class LZWFilter extends FileFilter {

public boolean accept(File f) {
        if (f.isDirectory()) {
            return true;
        }

        String extension = Utils.getExtension(f);
        if (extension != null) {
            if (extension.equals(Utils.lzw)){
                    return true;
            } else {
                return false;
            }
        }
        return false;
    }

 public String getDescription() {
        return "*.lzw";
    }
}
