public class Solution {
    public List<List<Integer>> permuteUnique_1(int[] num) {
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        List<Integer> path = new ArrayList<Integer>();
        Arrays.sort(num);
        boolean[] visited = new boolean[num.length];
        Arrays.fill(visited, false);
        permuteRe(num, res, path,visited);
        return res;
    }
    void permuteRe(int[] num, List<List<Integer>> res, List<Integer> path, boolean[] visited) {
        if(path.size() == num.length) {
            ArrayList<Integer> tmp = new ArrayList<Integer>(path);
            res.add(tmp);
            return;
        }
        for (int i = 0; i < num.length; ++i) {
            if(visited[i]||(i!=0&&num[i-1]==num[i]&&visited[i-1])) continue;
            visited[i] = true;
            path.add(num[i]);
            permuteRe(num, res, path, visited);
            path.remove(path.size() - 1);
            visited[i] = false;
        }
    }
    public boolean nextPermutation(int[] num) {
        int last = num.length - 1;
        int i = last;
        while (i > 0 && num[i - 1] >= num [i]) --i;
        for (int l = i, r = last; l < r; ++l, --r) {
            num[l] = num[l] ^ num[r];
            num[r] = num[l] ^ num[r];
            num[l] = num[l] ^ num[r];
        }
        if (i == 0) {
            return false;
        }
        int j = i;
        while (j <= last && num[i-1] >= num[j]) ++j;
        num[i-1] = num[i-1] ^ num[j];
        num[j] = num[i-1] ^ num[j];
        num[i-1] = num[i-1] ^ num[j];
        return true;
    }
    public List<List<Integer>> permuteUnique_2(int[] num) {
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        Arrays.sort(num);
        do {
            List<Integer> path = new ArrayList<Integer>();
            for (int i : num) path.add(i);
            res.add(path);
        } while(nextPermutation(num));
        return res;
    }
},31

public class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> res = new ArrayList<String>();
        dfs(s, new String(), 0, 0, res);
        return res;
    }
    public void dfs(String s, String ip, int start, int step, List<String> res) {
        if (step == 4 && start == s.length()) {
            res.add(ip);
        }
        if (step == 4) return;
        if(s.length()-start>(4-step)*3) return ;
        if(s.length()-start<4-step) return ;
        if (ip.length() != 0) ip+=".";
        int num = 0;
        for (int i = start; i < start + 3 && i < s.length(); ++i) {
            num =  num*10 + s.charAt(i) - '0';
            if (num > 255) break;
            ip += s.charAt(i);
            dfs(s, ip, i + 1, step + 1, res);
            if (num == 0) break;
        }
    }
},31

public class Solution {
    public int numDecodings(String s) {
        if (s.length() == 0 || s.charAt(0) == '0') return 0;
        int N = s.length();
        int f0 = 1, f1 = 1;
        for (int i = 1; i < N; ++i) {
            if (s.charAt(i) == '0') f1 = 0;
            int num = s.charAt(i) - '0' + (s.charAt(i-1) - '0') * 10;
            if (num < 10 || num > 26) {
                f0 = 0;
            }
            int tmp = f1;
            f1 = f1 + f0;
            f0 = tmp;
        }
        return f1;
    }
},31

