        FILE_TYPE_MAP.put("zip", "504B0304");
        FILE_TYPE_MAP.put("rar", "52617221");
        FILE_TYPE_MAP.put("psd", "38425053");  FILE_TYPE_MAP.put("eml", "44656C69766572792D646174653A");  FILE_TYPE_MAP.put("dbx", "CFAD12FEC5FD746F");  FILE_TYPE_MAP.put("pst", "2142444E");  FILE_TYPE_MAP.put("xls", "D0CF11E0");  FILE_TYPE_MAP.put("doc", "D0CF11E0");  FILE_TYPE_MAP.put("mdb", "5374616E64617264204A");  FILE_TYPE_MAP.put("wpd", "FF575043"); FILE_TYPE_MAP.put("eps", "252150532D41646F6265");
        FILE_TYPE_MAP.put("ps", "252150532D41646F6265");
        FILE_TYPE_MAP.put("pdf", "255044462D312E");  FILE_TYPE_MAP.put("qdf", "AC9EBD8F");  FILE_TYPE_MAP.put("pwl", "E3828596");  FILE_TYPE_MAP.put("wav", "57415645");  FILE_TYPE_MAP.put("avi", "41564920");
        FILE_TYPE_MAP.put("ram", "2E7261FD");  FILE_TYPE_MAP.put("rm", "2E524D46");  FILE_TYPE_MAP.put("mpg", "000001BA");  FILE_TYPE_MAP.put("mov", "6D6F6F76");  FILE_TYPE_MAP.put("asf", "3026B2758E66CF11"); FILE_TYPE_MAP.put("mid", "4D546864");  }

    public final static String getFileType(File file) {
        String filetype = null;
        byte[] b        = new byte[50];
        try (
                InputStream is = new FileInputStream(file)
        ) {
            is.read(b);
            filetype = getFileTypeByStream(b);
            is.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
        return filetype;
    }

    public final static String getFileTypeByStream(byte[] b) {
        String                             filetypeHex   = String.valueOf(getFileHexString(b));
        Iterator<Map.Entry<String,String>> entryiterator = FILE_TYPE_MAP.entrySet().iterator();
        while (entryiterator.hasNext()) {
            Map.Entry<String,String> entry = entryiterator.next();
            String fileTypeHexValue = entry.getValue();
            if (filetypeHex.toUpperCase().startsWith(fileTypeHexValue)) {
                return entry.getKey();
            }
        }
        return null;
    }

    public final static String getFileHexString(byte[] b) {
        StringBuilder stringBuilder = new StringBuilder();
        if (b == null || b.length <= 0) {
            return null;
        }
        for (int i = 0; i < b.length; i++) {
            int v = b[i] & 0xFF;
            String hv = Integer.toHexString(v);
            if (hv.length() < 2) {
                stringBuilder.append(0);
            }
            stringBuilder.append(hv);
        }
        return stringBuilder.toString();
    }
}
