package wyf.ytl.entity;                         import static wyf.ytl.tool.ConstantUtil.TILE_SIZE;

                                                                                                                                          public class MyDrawable implements Externalizable{
    private static final long serialVersionUID = 919144009679011682L;   
    public Bitmap bmpSelf;public int width;public int height;public int col;public int row;public int refCol;public int refRow;public int [][] noThrough;public boolean meetable;public void writeExternal(ObjectOutput out) throws IOException {
        out.writeInt(width);out.writeInt(height);out.writeInt(col);out.writeInt(row);out.writeInt(refCol);out.writeInt(refRow);out.writeObject(noThrough);out.writeBoolean(meetable);}
    public void readExternal(ObjectInput in) throws IOException,
            ClassNotFoundException {
        width = in.readInt();
        height = in.readInt();
        col = in.readInt();
        row = in.readInt();
        refCol = in.readInt();
        refRow = in.readInt();
        noThrough = (int[][]) in.readObject();
        meetable = in.readBoolean();
    }
    public MyDrawable(){}public MyDrawable(Bitmap bmpSelf,boolean meetable,int width,int height,int col,int row,int refCol,int refRow,int [][] noThrough){
        this.bmpSelf = bmpSelf;
        this.width = width;
        this.height = height;
        this.col = col;
        this.row = row;
        this.refCol = refCol;
        this.refRow = refRow;
        this.noThrough = noThrough;
        this.meetable = meetable;
    }
    public void drawSelf(Canvas canvas,int screenRow, int screenCol,int offsetX,int offsetY){
        int x = (screenCol-refCol)*TILE_SIZE;int y = screenRow*TILE_SIZE+(refRow+1)*TILE_SIZE-height;canvas.drawBitmap(bmpSelf, x-offsetX, y-offsetY, null);}
