package cn.itcast_03;








public class CopyFolderDemo {
    public static void main(String[] args) throws IOException {
        File srcFolder = new File("d:\\demo");

        File destFolder = new File(srcFolder.getName());
        if (!destFolder.exists()) {
            destFolder.mkdir();
        }

        File[] fileArray = srcFolder.listFiles();

        for (File file : fileArray) {
            String name = file.getName(); File newFile = new File(destFolder, name); copy(file, newFile);
        }
    }

    private static void copy(File file, File newFile) throws IOException {
        BufferedInputStream bis = new BufferedInputStream(new FileInputStream(
                file));
        BufferedOutputStream bos = new BufferedOutputStream(
                new FileOutputStream(newFile));

        byte[] bys = new byte[1024];
        int len = 0;
        while ((len = bis.read(bys)) != -1) {
            bos.write(bys, 0, len);
        }

        bos.close();
        bis.close();
    }

}
